GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
CREATE TABLE Student (sid INT NOT NULL PRIMARY KEY, fullName NVARCHAR(50) NOT NULL);
CREATE TABLE Course (cid CHAR(6) NOT NULL PRIMARY KEY, title NVARCHAR(60) NOT NULL);
