ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. One change → one audit row 6.0 → 8.5 | Một thay đổi → một dòng 6,0 → 8,5', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

