SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN; UPDATE Enrolment SET grade = CASE sid WHEN 1 THEN 6.0 WHEN 2 THEN 9.0 ELSE 5.0 END WHERE cid = ''DBI202'';
