SET @info = CONCAT(N''audit rows: '', (SELECT COUNT(*) FROM GradeAudit), N'' (expected 2: Bình 7.5 → 9.0 and Chi NULL → 5.0; An unchanged)''); ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
