WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. A three-row UPDATE logs only the real changes (NULL → 5 counts) | UPDATE ba dòng chỉ ghi các thay đổi thật (NULL → 5 cũng tính)'; END
