BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN; UPDATE Enrolment SET grade = grade WHERE cid = ''PRF192'';
SET @ok = IIF((SELECT COUNT(*) FROM GradeAudit) = 0, 1, 0); SET @info = CONCAT(N''audit rows: '', (SELECT COUNT(*) FROM GradeAudit)); ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. An UPDATE that changes nothing logs nothing | UPDATE không đổi gì thì không ghi gì'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. An UPDATE that changes nothing logs nothing | UPDATE không đổi gì thì không ghi gì', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
