GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 4 checks ──────────';

-- CHECK 1: Insert three employees into two departments
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN;
INSERT INTO tblEmployee (empSSN, empName, depNum) VALUES (30121050200, N''A'', 4), (30121050201, N''B'', 4), (30121050202, N''C'', 5);
DECLARE @a INT = (SELECT COUNT(*) FROM (SELECT depNum, empCount FROM tblDepartment) AS a_), @b INT = (SELECT COUNT(*) FROM (SELECT d.depNum, COUNT(e.empSSN) AS empCount FROM tblDepartment d LEFT JOIN tblEmployee e ON e.depNum = d.depNum GROUP BY d.depNum) AS b_);
SET @ok = IIF(@a = @b AND NOT EXISTS (SELECT depNum, empCount FROM tblDepartment EXCEPT SELECT d.depNum, COUNT(e.empSSN) AS empCount FROM tblDepartment d LEFT JOIN tblEmployee e ON e.depNum = d.depNum GROUP BY d.depNum) AND NOT EXISTS (SELECT d.depNum, COUNT(e.empSSN) AS empCount FROM tblDepartment d LEFT JOIN tblEmployee e ON e.depNum = d.depNum GROUP BY d.depNum EXCEPT SELECT depNum, empCount FROM tblDepartment), 1, 0);
SET @info = CONCAT(N''your result: '', @a, N'' rows; expected: '', @b, N'' rows'', IIF(@a = @b, N'' (same count, different values)'', N''''));
IF @@TRANCOUNT > 0 ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
